import csv
from collections import defaultdict
rows = list(csv.DictReader(open('ae_ip_termination_by_month.csv')))
cols = list(rows[0].keys())
print('cols:', cols, 'n:', len(rows))
def find(name):
    for c in cols:
        if name.lower() in c.lower():
            return c
    return None
diag_c = find('diag'); mon_c = find('month'); act_c = find('recover') or find('actual'); exp_c = find('expect'); ae_c = find('ae') or find('ratio')
print('mapped:', diag_c, mon_c, act_c, exp_c, ae_c)
agg = defaultdict(lambda: [0.0,0.0])
for r in rows:
    a = float(r[act_c]); e = float(r[exp_c])
    agg[r[diag_c]][0]+=a; agg[r[diag_c]][1]+=e
for d,(a,e) in sorted(agg.items()):
    print(d, 'pooled AE=', round(a/e,4) if e else None, 'exp=', round(e,1))
cv = []
for r in sorted(rows, key=lambda r: (str(r[diag_c]), str(r[mon_c]))):
    if r[diag_c]=='Cardiovascular':
        ae = float(r[ae_c]) if ae_c and r[ae_c] not in ('','NA') else (float(r[act_c])/float(r[exp_c]) if float(r[exp_c]) else None)
        cv.append((r[mon_c], round(ae,3) if ae is not None else None, round(float(r[exp_c]),1)))
print('CV by month (month, AE, expected):')
for x in cv: print(x)
